<?php
$pdo=db();
$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');
$st=$pdo->prepare("SELECT COUNT(*) orders_count,COALESCE(SUM(total_amount),0) revenue FROM orders WHERE DATE(created_at) BETWEEN ? AND ? AND status<>'cancelled'");$st->execute([$from,$to]);$summary=$st->fetch();
$st=$pdo->prepare("SELECT source,COUNT(*) orders_count,COALESCE(SUM(total_amount),0) revenue FROM orders WHERE DATE(created_at) BETWEEN ? AND ? AND status<>'cancelled' GROUP BY source");$st->execute([$from,$to]);$channelRows=$st->fetchAll();$channels=['online'=>['orders_count'=>0,'revenue'=>0],'pos'=>['orders_count'=>0,'revenue'=>0]];foreach($channelRows as $cr)$channels[$cr['source']]=$cr;
$st=$pdo->prepare("SELECT product_name,SUM(quantity) qty,SUM(line_total) revenue FROM order_details d JOIN orders o ON o.id=d.order_id WHERE DATE(o.created_at) BETWEEN ? AND ? AND o.status<>'cancelled' GROUP BY product_id,product_name ORDER BY qty DESC LIMIT 8");$st->execute([$from,$to]);$best=$st->fetchAll();
$daily=$pdo->prepare("SELECT DATE(created_at) day,SUM(total_amount) revenue FROM orders WHERE DATE(created_at) BETWEEN ? AND ? AND status<>'cancelled' GROUP BY DATE(created_at) ORDER BY day");$daily->execute([$from,$to]);$days=$daily->fetchAll();
?>
<section class="page-intro"><div><span class="eyebrow">BUSINESS INTELLIGENCE</span><h2>Báo cáo & thống kê</h2><p class="muted">Tổng hợp kết quả kinh doanh theo khoảng thời gian.</p></div></section>
<section class="card"><form method="get" class="filter-form"><input type="hidden" name="page" value="reports"><label>Từ ngày<input type="date" name="from" value="<?= e($from) ?>"></label><label>Đến ngày<input type="date" name="to" value="<?= e($to) ?>"></label><button class="btn primary">Lọc dữ liệu</button></form></section>
<div class="stats-grid two"><article class="stat-card"><div class="stat-top">Doanh thu</div><strong><?= money($summary['revenue']) ?></strong><small>Không tính đơn đã hủy</small></article><article class="stat-card"><div class="stat-top">Số đơn hàng</div><strong><?= (int)$summary['orders_count'] ?></strong><small>Trong khoảng thời gian chọn</small></article></div>
<section class="channel-report-grid"><article class="card"><span class="eyebrow">ONLINE STORE</span><h3>Đơn từ website</h3><strong><?= (int)$channels['online']['orders_count'] ?> đơn</strong><p><?= money($channels['online']['revenue']) ?></p></article><article class="card"><span class="eyebrow">POINT OF SALE</span><h3>Đơn tại quầy</h3><strong><?= (int)$channels['pos']['orders_count'] ?> đơn</strong><p><?= money($channels['pos']['revenue']) ?></p></article></section>
<section class="card"><div class="card-heading"><h3>Sản phẩm bán chạy</h3></div><div class="table-wrap"><table><thead><tr><th>Sản phẩm</th><th>Số lượng bán</th><th>Doanh thu</th></tr></thead><tbody><?php foreach($best as $b): ?><tr><td><?= e($b['product_name']) ?></td><td><?= (int)$b['qty'] ?></td><td><?= money($b['revenue']) ?></td></tr><?php endforeach; ?><?php if(!$best): ?><tr><td colspan="3" class="empty">Chưa có dữ liệu trong khoảng thời gian này.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="card"><div class="card-heading"><h3>Doanh thu theo ngày</h3></div><div class="chart-bars"><?php $max=max(array_map(fn($x)=>(float)$x['revenue'],$days)?:[1]); foreach($days as $d): ?><div class="chart-col"><div class="bar-value"><?= money($d['revenue']) ?></div><div class="bar-track"><div class="bar" style="height:<?= max(3,((float)$d['revenue']/$max)*100) ?>%"></div></div><small><?= date('d/m',strtotime($d['day'])) ?></small></div><?php endforeach; ?></div></section>
